class Inventory {
  readonly name: string;
  private counts = new Map<string, number>();
  protected changes = 0;

  constructor(name: string) {
    this.name = name;
  }

  add(sku: string, qty: number): number {
    const next = (this.counts.get(sku) ?? 0) + qty;
    this.counts.set(sku, next);
    this.changes += 1;
    return next;
  }
}

class AuditedInventory extends Inventory {
  report(): string {
    return `${this.name}: ${this.changes} changes`;  // protected: OK in a subclass
  }
}

const inv = new AuditedInventory("main");
inv.add("pen", 3);
inv.name = "other";   // error: Cannot assign to 'name' because it is a read-only property
inv.counts;           // error: Property 'counts' is private
inv.changes;          // error: Property 'changes' is protected

class Session {
  constructor(
    readonly userId: string,
    private readonly now: () => number,   // injected clock, private to the class
  ) {}

  isExpired(startedAt: number): boolean {
    return this.now() - startedAt > 30 * 60_000;
  }
}
